import{_ as r,H as l,o as a,c as n,aO as e,q as d,s as i,a as s,l as c,aU as D}from"./chunks/framework.vjUPZZJn.js";const _=JSON.parse('{"title":"DDS DCPS 规范：实体模型与 QoS 策略","description":"","frontmatter":{"date":"2026-10-26T10:20:00.000Z","title":"DDS DCPS 规范：实体模型与 QoS 策略","source":[[["1-知识/中间件/DDS/02 DDS 核心 - DCPS"]],[["1-知识/中间件/DDS/DDS 核心概念解析：DomainParticipant（域参与者）"]]],"tags":["中间件","学习笔记","DDS"],"categories":["计算机"],"permalink":"/pages/3be7d9"},"headers":[],"relativePath":"计算机/DDS DCPS 规范：实体模型与 QoS 策略.md","filePath":"计算机/DDS DCPS 规范：实体模型与 QoS 策略.md","lastUpdated":1793001236000}'),g={name:"计算机/DDS DCPS 规范：实体模型与 QoS 策略.md"};function S(h,t,p,u,P,E){const o=l("Mermaid");return a(),n("div",null,[t[2]||(t[2]=e('<h1 id="dds-dcps-规范-实体模型与-qos-策略" tabindex="-1">DDS DCPS 规范：实体模型与 QoS 策略 <a class="header-anchor" href="#dds-dcps-规范-实体模型与-qos-策略" aria-label="Permalink to &quot;DDS DCPS 规范：实体模型与 QoS 策略&quot;">​</a></h1> <p>DCPS（Data-Centric Publish-Subscribe，以数据为中心的发布/订阅）规范是 DDS 规范族最初也是最核心的规范，在某些场合 DDS 规范指的就是 DCPS。本文整理 DCPS 的两块核心内容：实体模型（应用如何通过一组实体接入 DDS 通信，其中 DomainParticipant 是整个体系的入口）与 QoS 策略（DDS 1.4 定义的 22 种标准策略及其分组）。读完可以对 DDS 编程模型的整体结构建立认识，并掌握实体生命周期与 QoS 配置的常见实践。</p> <h2 id="dcps-的内容构成" tabindex="-1">DCPS 的内容构成 <a class="header-anchor" href="#dcps-的内容构成" aria-label="Permalink to &quot;DCPS 的内容构成&quot;">​</a></h2> <p>DCPS 规范的内容分为三大块：</p> <ul><li><strong>模型描述</strong>：介绍模型中涉及的概念，即下文的实体模型与数据描述；</li> <li><strong>接口描述</strong>：分模块定义类并定义接口形式及接口功能描述；</li> <li><strong>QoS 定义</strong>：定义 22 种 QoS 的功能及其配置方式。</li></ul> <h2 id="实体模型" tabindex="-1">实体模型 <a class="header-anchor" href="#实体模型" aria-label="Permalink to &quot;实体模型&quot;">​</a></h2> <p>DCPS 实体模型定义了三层实体（参与者层、发布/订阅/主题层、读写者层），层级关系如下：</p> ',14)),(a(),d(D,null,{default:i(()=>[c(o,{id:"mermaid-35",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20DP%5B%22DomainParticipant%EF%BC%88%E5%9F%9F%E5%8F%82%E4%B8%8E%E8%80%85%EF%BC%8C%E5%AE%9E%E4%BD%93%E4%BD%93%E7%B3%BB%E6%A0%B9%E8%8A%82%E7%82%B9%EF%BC%89%22%5D%0A%20%20%20%20T%5B%22Topic%EF%BC%88%E4%B8%BB%E9%A2%98%EF%BC%89%22%5D%0A%20%20%20%20P%5B%22Publisher%EF%BC%88%E5%8F%91%E5%B8%83%E8%80%85%EF%BC%89%22%5D%0A%20%20%20%20S%5B%22Subscriber%EF%BC%88%E8%AE%A2%E9%98%85%E8%80%85%EF%BC%89%22%5D%0A%20%20%20%20DW%5B%22DataWriter%EF%BC%88%E6%95%B0%E6%8D%AE%E5%86%99%E5%85%A5%E8%80%85%EF%BC%89%22%5D%0A%20%20%20%20DR%5B%22DataReader%EF%BC%88%E6%95%B0%E6%8D%AE%E8%AF%BB%E5%8F%96%E8%80%85%EF%BC%89%22%5D%0A%20%20%20%20DP%20--%3E%20T%0A%20%20%20%20DP%20--%3E%20P%0A%20%20%20%20DP%20--%3E%20S%0A%20%20%20%20P%20--%3E%20DW%0A%20%20%20%20S%20--%3E%20DR%0A%20%20%20%20DW%20-.%E5%85%B3%E8%81%94.-%20T%0A%20%20%20%20DR%20-.%E5%85%B3%E8%81%94.-%20T%0A"})]),fallback:i(()=>[...t[0]||(t[0]=[s(`
          Loading...
        `,-1)])]),_:1})),t[3]||(t[3]=e('<p>各实体的职责：</p> <ul><li><strong>Domain</strong>：代表一个通信平面，由 Domain ID 唯一标识，只有同一个域内的通信实体才可以通信。如果考虑车内通信，可以只划分 1 个 Domain，也可以按照交互规则或其他规则定义多个 Domain。</li> <li><strong>DomainParticipant</strong>：代表域内通信的应用程序的本地成员身份，可以理解为&quot;某个进程（或应用实例）加入到一个 DDS 通信域后的代表对象&quot;。它是 DDS 实体体系的根节点和入口，负责把应用纳入 DDS 的发现与通信机制中。</li> <li><strong>Topic</strong>：数据的抽象概念，由 TopicName 标识并关联相应的数据类型（DataType）。把域内所有 Topic 集合在一起，就形成一个虚拟的全局数据空间（Global Data Space），进一步弱化了节点的概念。</li> <li><strong>Publisher</strong>：发布者，发布主题数据，至少与 1 个 DataWriter 关联，通过调用 DataWriter 的相关函数将数据发出去。</li> <li><strong>Subscriber</strong>：订阅者，订阅主题数据，至少与 1 个 DataReader 关联。数据到达时，应用程序可能在忙于执行其他操作，也可能正在等待该消息，因此存在同步访问和异步通知两种方式。</li> <li><strong>DataWriter</strong>：数据写入者，类似缓存，把需要发布的主题数据从应用层写入 DataWriter。</li> <li><strong>DataReader</strong>：数据读取者，同样可以理解为一种缓存，从订阅者得到主题数据，随之传给应用层。</li></ul> <h2 id="domainparticipant-通信的入口" tabindex="-1">DomainParticipant：通信的入口 <a class="header-anchor" href="#domainparticipant-通信的入口" aria-label="Permalink to &quot;DomainParticipant：通信的入口&quot;">​</a></h2> <p>没有 DomainParticipant，应用就无法接入 DDS 网络，无法进行服务发现，也无法收发数据。这一节展开它的定位、使用条件与工程实践。</p> <h3 id="域与参与者" tabindex="-1">域与参与者 <a class="header-anchor" href="#域与参与者" aria-label="Permalink to &quot;域与参与者&quot;">​</a></h3> <table tabindex="0"><thead><tr><th style="text-align:left;">概念</th> <th style="text-align:left;">定义</th> <th style="text-align:left;">类比</th></tr></thead> <tbody><tr><td style="text-align:left;">Domain（域）</td> <td style="text-align:left;">一个逻辑隔离的通信空间，由唯一的 <code>domain_id</code> 标识。不同 Domain 之间默认互不发现、互不通信。</td> <td style="text-align:left;">房间号，不同的房间互不相通。</td></tr> <tr><td style="text-align:left;">DomainParticipant</td> <td style="text-align:left;">应用在某个 <code>domain_id</code> 中的具体实例。创建它意味着该进程正式&quot;进入&quot;了该房间。</td> <td style="text-align:left;">进入房间的人，只有进了房间才能和其他人交流。</td></tr></tbody></table> <p>DomainParticipant 是应用接入 DDS 发现机制与通信机制的唯一凭证。</p> <h3 id="核心职责" tabindex="-1">核心职责 <a class="header-anchor" href="#核心职责" aria-label="Permalink to &quot;核心职责&quot;">​</a></h3> <ul><li><strong>身份标识与归属</strong>：绑定域 ID，声明&quot;我属于哪个域&quot;；携带实现相关的本地信息（如 GUID、QoS 策略），供其他参与者发现和匹配。</li> <li><strong>发现与资源管理的边界</strong>：DDS 的自动发现机制通常以 Participant 为粒度进行——对外广播自己的存在并监听其他 Participant 的加入；对内托管其下属所有 DDS 实体（Topic、Publisher、Subscriber、DataWriter、DataReader），可以视为 DDS 在该进程中的运行时上下文。</li> <li><strong>工厂角色</strong>：Participant 充当工厂，负责创建 Topic、Publisher 和 Subscriber。</li> <li><strong>生命周期管理</strong>：标准 DDS（RTI Connext、Fast DDS 等）要求先调用 <code>delete_contained_entities()</code>（或逐个删除子实体）之后，才能通过 <code>DomainParticipantFactory::delete_participant()</code> 删除参与者；直接删除仍含有子实体的 Participant 会失败（返回 <code>RETCODE_PRECONDITION_NOT_MET</code>）。部分实现的封装接口会代为自动清理，但不是规范行为。</li></ul> <h3 id="通信建立的必要条件" tabindex="-1">通信建立的必要条件 <a class="header-anchor" href="#通信建立的必要条件" aria-label="Permalink to &quot;通信建立的必要条件&quot;">​</a></h3> <p>两个应用想要通过 DDS 成功通信，必须同时满足以下条件，其中第一条直接由 DomainParticipant 决定：</p> <ol><li><strong>相同的 <code>domain_id</code></strong>：如果两个 Participant 不在同一个 Domain ID 下，它们甚至无法互相&quot;看见&quot;，更无法建立连接。</li> <li><strong>Topic 匹配</strong>：Topic 名称相同，数据类型（Type）兼容。</li> <li><strong>QoS 策略兼容</strong>：可靠性（Reliability）、历史深度（History）、截止时间（Deadline）等策略必须匹配。</li> <li><strong>网络与安全</strong>：网络可达（UDP/TCP 端口通畅）；若启用 DDS Security，需通过身份认证和权限校验。</li></ol> <p>排查&quot;收不到数据&quot;的问题时，首先应检查双方是否创建了相同 <code>domain_id</code> 的 Participant。</p> <h3 id="一个进程需要几个-participant" tabindex="-1">一个进程需要几个 Participant <a class="header-anchor" href="#一个进程需要几个-participant" aria-label="Permalink to &quot;一个进程需要几个 Participant&quot;">​</a></h3> <p>绝大多数场景下，一个应用程序进程只需要创建一个 DomainParticipant：</p> <ul><li><strong>资源开销小</strong>：发现协议流量、内置端点（Built-in Endpoints）、线程池、Socket 连接等资源通常按 Participant 分配。</li> <li><strong>管理简单</strong>：配置集中，逻辑清晰。</li></ul> <p>仅在确有必要时，才在一个进程中创建多个不同 <code>domain_id</code> 或不同配置的 Participant：</p> <ul><li><strong>多域网关</strong>：进程需要同时作为桥梁，连接两个不同的逻辑域（例如 <code>domain_id=0</code> 和 <code>domain_id=1</code>）。</li> <li><strong>强隔离需求</strong>：需要在同一进程内隔离不同的安全身份、完全不同的 QoS 配置或独立的发现组。</li></ul> <p>代价是资源消耗成倍增加（内存、线程、网络端口），配置复杂度与调试难度上升。除非有明确的多域互通或强隔离需求，坚持一个进程一个 Participant。</p> <h3 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h3> <table tabindex="0"><thead><tr><th style="text-align:left;">误区</th> <th style="text-align:left;">正确理解</th></tr></thead> <tbody><tr><td style="text-align:left;">&quot;Participant 就是发布/订阅者&quot;</td> <td style="text-align:left;">错。Participant 是容器；Publisher/Subscriber 才是具体的发布/订阅角色。</td></tr> <tr><td style="text-align:left;">&quot;一个进程只能有一个 Participant&quot;</td> <td style="text-align:left;">错。技术上允许创建多个，但通常不建议，除非为了多域隔离。</td></tr> <tr><td style="text-align:left;">&quot;Participant 对应物理机器&quot;</td> <td style="text-align:left;">错。它对应的是 DDS 通信栈的一个实例。一台机器上可以运行多个进程，每个进程都有自己的 Participant。</td></tr> <tr><td style="text-align:left;">&quot;它是业务逻辑对象&quot;</td> <td style="text-align:left;">错。它是基础设施对象，类似于网络编程中的 Socket 或 Context，而非业务实体。</td></tr></tbody></table> <h2 id="数据描述-主题、实例与样本" tabindex="-1">数据描述：主题、实例与样本 <a class="header-anchor" href="#数据描述-主题、实例与样本" aria-label="Permalink to &quot;数据描述：主题、实例与样本&quot;">​</a></h2> <table tabindex="0"><thead><tr><th style="text-align:left;">概念</th> <th style="text-align:left;">说明</th> <th style="text-align:left;">标识</th></tr></thead> <tbody><tr><td style="text-align:left;">主题</td> <td style="text-align:left;">最大类，域内唯一的主题名称，并关联 1 个数据类型。</td> <td style="text-align:left;">主题名+类型</td></tr> <tr><td style="text-align:left;">实例</td> <td style="text-align:left;">主题数据中 key 成员相同的数据的集合，即使用 key 成员进一步区分主题数据，可以理解成&quot;子主题&quot;。</td> <td style="text-align:left;">InstanceHandle_t</td></tr> <tr><td style="text-align:left;">样本</td> <td style="text-align:left;">每次向 DDS 发送一次数据产生一个数据样本。</td> <td style="text-align:left;">序列号</td></tr></tbody></table> <h2 id="_22-种标准-qos-策略" tabindex="-1">22 种标准 QoS 策略 <a class="header-anchor" href="#_22-种标准-qos-策略" aria-label="Permalink to &quot;22 种标准 QoS 策略&quot;">​</a></h2> <p>QoS（Quality of Service）即服务质量。DDS 规范中定义了 22 种标准 QoS 策略（DDS 1.4 规范 §2.2.3），用于精细控制数据通信的行为，涵盖可靠性、持久性、资源管理、发现机制、数据呈现等多个维度。这些策略可应用于不同的 DDS 实体（如 DomainParticipant、Publisher/Subscriber、DataWriter/DataReader、Topic），并支持匹配协商机制以确保通信双方兼容。</p> <h3 id="与数据传输行为相关的策略" tabindex="-1">与数据传输行为相关的策略 <a class="header-anchor" href="#与数据传输行为相关的策略" aria-label="Permalink to &quot;与数据传输行为相关的策略&quot;">​</a></h3> <ol><li><strong>Reliability（可靠性）</strong>：控制是否保证数据送达：<code>BEST_EFFORT</code>（尽力而为）或 <code>RELIABLE</code>（可靠传输）。</li> <li><strong>Durability（持久性）</strong>：控制历史数据对晚加入订阅者的可用性：<code>VOLATILE</code>、<code>TRANSIENT_LOCAL</code>、<code>TRANSIENT</code>、<code>PERSISTENT</code>。</li> <li><strong>History（历史记录）</strong>：定义每个实例保留多少样本：<code>KEEP_LAST</code>（保留最近 N 个）或 <code>KEEP_ALL</code>（保留全部）。</li> <li><strong>Deadline（截止时间）</strong>：要求数据必须在指定周期内更新，否则触发事件。</li> <li><strong>LatencyBudget（延迟预算）</strong>：允许应用指定可接受的最大端到端传输延迟。</li> <li><strong>Ownership（所有权）</strong>：支持独占或共享数据写入权，避免多个发布者冲突。</li> <li><strong>OwnershipStrength（所有权强度）</strong>：配合 Ownership 使用，数值高的 DataWriter 获得写入优先权。</li> <li><strong>Liveliness（活跃性）</strong>：检测 DataWriter 是否&quot;存活&quot;：<code>AUTOMATIC</code>、<code>MANUAL_BY_PARTICIPANT</code>、<code>MANUAL_BY_TOPIC</code>。</li> <li><strong>TimeBasedFilter（基于时间的过滤）</strong>：限制 DataReader 接收数据的最大频率（如每 100ms 最多一次）。</li></ol> <p>设置为 BEST_EFFORT 就一定不可靠吗？不一定。DDS 里定义的可靠性 QoS 指的是&quot;是否需要 DDS 做额外的可靠保证&quot;，比如传输层使用 TCP 或其他底层协议已经保证了可靠传输，这时配置 BEST_EFFORT 同样可以实现可靠的传输。</p> <p>设置为 RELIABLE 就一定可靠吗？同样不一定。可靠的实现方式是确认重传：在接收方确认之前，数据需要缓存在队列中以备可能的重传，而队列有长度限制（无论存储在内存还是文件中，都受限于存储空间）。当队列到达上限且需要发送新样本时：</p> <ul><li>替换老的样本数据：被替换的数据丢包后无法重传，造成&quot;丢包&quot;，无法实现可靠；</li> <li>阻塞等待队列有额外空间：可以实现&quot;感知上&quot;的可靠。</li></ul> <h3 id="与资源管理与限制相关的策略" tabindex="-1">与资源管理与限制相关的策略 <a class="header-anchor" href="#与资源管理与限制相关的策略" aria-label="Permalink to &quot;与资源管理与限制相关的策略&quot;">​</a></h3> <ol start="10"><li><strong>ResourceLimits（资源限制）</strong>：限制缓存中最大样本数、实例数、每个实例的样本数等。</li> <li><strong>Presentation（表示）</strong>：控制同一 Publisher/Subscriber 下多个 DataWriter/DataReader 的数据呈现顺序和范围（<code>INSTANCE</code>、<code>TOPIC</code>、<code>GROUP</code> 级别）。</li> <li><strong>Partition（分区）</strong>：在 Domain 内创建逻辑子通道，只有相同 Partition 的发布/订阅才能通信。</li> <li><strong>DestinationOrder（目标排序）</strong>：控制 DataReader 接收样本的顺序：按源时间戳（<code>BY_SOURCE_TIMESTAMP</code>）或接收顺序（<code>BY_RECEPTION_TIMESTAMP</code>）。</li></ol> <h3 id="与元数据与用户自定义信息相关的策略" tabindex="-1">与元数据与用户自定义信息相关的策略 <a class="header-anchor" href="#与元数据与用户自定义信息相关的策略" aria-label="Permalink to &quot;与元数据与用户自定义信息相关的策略&quot;">​</a></h3> <ol start="14"><li><strong>UserData（用户数据）</strong>：允许在 DomainParticipant、Publisher 等实体上附加任意二进制元数据。</li> <li><strong>TopicData（主题数据）</strong>：附加到 Topic 的元数据，传播给所有基于该 Topic 的读写器。</li> <li><strong>GroupData（组数据）</strong>：附加到 Publisher/Subscriber 的元数据，传播给其下属所有 DataWriter/DataReader。</li></ol> <h3 id="与生命周期与发现机制相关的策略" tabindex="-1">与生命周期与发现机制相关的策略 <a class="header-anchor" href="#与生命周期与发现机制相关的策略" aria-label="Permalink to &quot;与生命周期与发现机制相关的策略&quot;">​</a></h3> <ol start="17"><li><strong>EntityFactory（实体工厂）</strong>：控制由工厂创建的实体在创建时是否自动启用（<code>autoenable</code>，默认启用）。</li> <li><strong>WriterDataLifecycle（写者数据生命周期）</strong>：控制 DataWriter 是否在删除时自动注销其实例。</li> <li><strong>ReaderDataLifecycle（读者数据生命周期）</strong>：控制 DataReader 是否自动清除未更新的实例。</li> <li><strong>DurabilityService（持久化服务）</strong>：配置当 Durability 为 <code>TRANSIENT</code> 或 <code>PERSISTENT</code> 时，外部持久化服务的行为（如清理延迟、历史深度等）。</li></ol> <h3 id="其余标准策略" tabindex="-1">其余标准策略 <a class="header-anchor" href="#其余标准策略" aria-label="Permalink to &quot;其余标准策略&quot;">​</a></h3> <ol start="21"><li><strong>TransportPriority（传输优先级）</strong>：为数据流设置网络传输优先级（依赖底层传输支持）。</li> <li><strong>Lifespan（生命周期）</strong>：指定数据样本的有效生存时间，超时后自动丢弃。</li></ol> <p>以上 22 种即 DDS 1.4 DCPS 规范定义的标准 QoS 全集。各扩展规范与具体实现还提供额外策略，如 XTypes 的 TypeConsistencyEnforcement（类型一致性强化）、部分实现中用于避免自收的 IgnoreLocal 配置等，均不计入这 22 种之内。</p> <h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2> <ul><li>DCPS 是 DDS 规范族的核心，内容分为模型描述、接口描述、QoS 定义三大块</li> <li>实体模型分三层：DomainParticipant 是根节点和工厂，Publisher/Subscriber 各自关联 DataWriter/DataReader，Topic 关联数据类型</li> <li>通信建立的四个条件：相同 domain_id、Topic 与类型匹配、QoS 兼容、网络与安全可达——排查收不到数据先查 domain_id</li> <li>一个进程默认一个 Participant；多 Participant 仅用于多域网关与强隔离场景</li> <li>删除 Participant 前必须先 <code>delete_contained_entities()</code>，直接删除会返回 <code>RETCODE_PRECONDITION_NOT_MET</code></li> <li>22 种标准 QoS 覆盖传输行为、资源管理、元数据、生命周期四个方向；BEST_EFFORT 与 RELIABLE 的实际可靠性都取决于传输层与队列容量</li></ul>',81))])}const T=r(g,[["render",S]]);export{_ as __pageData,T as default};
